// Read an env variable with a default. n8n 2.x blocks $env unless
// N8N_BLOCK_ENV_ACCESS_IN_NODE=false; fall back to the default in that case.
const env = (name, fallback) => {
  try {
    const value = $env[name];
    return value === undefined || value === '' ? fallback : value;
  } catch (error) {
    return fallback;
  }
};
const webhook = env('ALERT_WEBHOOK_URL', '');
if (!webhook) {
  console.log('ALERT_WEBHOOK_URL not set; skipping failure alert');
  return [];
}
const redact = (s) => String(s ?? '')
  .replace(/sk-[A-Za-z0-9_-]{8,}/g, 'sk-***')
  .replace(/Bearer\s+[A-Za-z0-9._~+\/-]+/gi, 'Bearer ***')
  .replace(/((?:access_|api_)?token|key|secret|password)=[^&\s]+/gi, '$1=***');
const e = $json;
const workflow = e.workflow?.name || 'unknown workflow';
const node = e.execution?.lastNodeExecuted || e.trigger?.node?.name || 'unknown node';
const error = redact(e.execution?.error?.message || e.trigger?.error?.message || 'Unknown error').slice(0, 500);
let text = `n8n workflow failed\nWorkflow: ${workflow}\nNode: ${node}\nError: ${error}`;
if (e.execution?.url) text += `\nExecution: ${e.execution.url}`;
// "text" is read by Slack-style webhooks, "content" by Discord-style webhooks.
return [{ json: { webhook, payload: { text, content: text } } }];
